# November 19, 2026: Prince County, Prince Edward Island (outside Summerside). Region pe drawn by tools/choose.py --claim
# with --state limited to the eastern provinces; the two earlier PEI batches (pe_bhrt, pe_rhhz) hold only Queens County,
# so this batch takes the western county. Sources opened in this session: the Canadian Register of Historic Places
# statement for each place (historicplaces.ca, read with tools/page.py --all; ids from the {{HPC row}} templates of the
# Wikipedia "List of historic places in Prince County, Prince Edward Island"); Tourism PEI's operator pages (dates of
# operation only, never times); the Diocese of Charlottetown's Mass-times table; the Anglican Parish of Port Hill's
# history page; the Indian River Festival's page; CBC News; OpenStreetMap (tools/nom.py) for positions.
from data_b import N
from data_ma import W
def L(t,u): return [t,u]
def HP(t,i): return ['Canadian Register of Historic Places: '+t,'https://www.historicplaces.ca/en/rep-reg/place-lieu.aspx?id=%d'%i]
def TP(t,u): return ['Tourism PEI: '+t,u]
BATCH={'key':'pe_tpau','label':'Prince County, Prince Edward Island','added':'2026-11-19 22:13'}
